# Let me try to extend Paley(13) to K_22 by adding vertices one at a time
# using a SAT/backtracking approach

import itertools
import random

n = 22
base_n = 13

# Paley(13) coloring
qr = {1, 3, 4, 9, 10, 12}
base_colors = []
for i in range(base_n):
    for j in range(i+1, base_n):
        d = (j - i) % 13
        if d in qr:
            base_colors.append(0)  # red
        else:
            base_colors.append(1)  # blue

# Build adjacency matrix for base
def build_adj(colors, n):
    adj = [[0]*n for _ in range(n)]
    idx = 0
    for i in range(n):
        for j in range(i+1, n):
            adj[i][j] = colors[idx]
            adj[j][i] = colors[idx]
            idx += 1
    return adj

base_adj = build_adj(base_colors, base_n)

# Now let's try to add 9 more vertices
# For each new vertex, we need to assign colors to its edges to all existing vertices
# This is like a constraint satisfaction problem

# Let me try a randomized greedy approach with backtracking

def try_extend(max_attempts=100000):
    for attempt in range(max_attempts):
        # Start with base adjacency
        adj = [row[:] for row in base_adj]
        # Add new vertices
        for v in range(base_n, n):
            # Assign edges to existing vertices
            for u in range(v):
                adj[v][u] = random.randint(0, 1)
                adj[u][v] = adj[v][u]

        # Check for violations
        violations = find_violations(adj, n)
        if not violations:
            return adj

    return None

def find_violations(adj, n):
    violations = []
    # Check red K_5
    for combo in itertools.combinations(range(n), 5):
        ok = True
        for i, j in itertools.combinations(combo, 2):
            if adj[i][j] != 0:
                ok = False
                break
        if ok:
            violations.append(('red', combo))
            if len(violations) > 10:  # Early exit
                return violations
    # Check blue K_4
    for combo in itertools.combinations(range(n), 4):
        ok = True
        for i, j in itertools.combinations(combo, 2):
            if adj[i][j] != 1:
                ok = False
                break
        if ok:
            violations.append(('blue', combo))
            if len(violations) > 10:
                return violations
    return violations

print("Trying random extension...")
result = try_extend(5000)
if result:
    print("Found!")
    # Convert to list
    colors = []
    for i in range(n):
        for j in range(i+1, n):
            colors.append(result[i][j])
    print(colors)
else:
